<div class="page-header d-print-none mb-3"><div class="row align-items-center"><div class="col"><div class="page-pretitle">Integrasi Sistem Informasi Faskes</div><h2 class="page-title">Fasilitas Kesehatan</h2></div><?php if($can('branches.manage')): ?><div class="col-auto"><a class="btn btn-teal" href="<?= site_url('faskes/create') ?>">+ Tambah faskes</a></div><?php endif ?></div></div>
<div class="card"><div class="table-responsive"><table class="table table-vcenter card-table"><thead><tr><th>Faskes</th><th>Endpoint</th><th>Status sinkron</th><th>Terakhir sinkron</th><th class="w-1"></th></tr></thead><tbody><?php foreach($branches as $b): ?><tr><td><div class="fw-semibold"><?= html_escape($b->name) ?></div><div class="text-secondary small"><?= html_escape($b->code) ?> · <?= html_escape($b->timezone) ?></div></td><td><span class="text-secondary"><?= html_escape($b->base_url) ?></span></td><td><?php $ok=$b->last_sync_status==='success'; ?><span class="status-dot bg-<?= $ok?'success':($b->last_sync_status==='failed'?'danger':'secondary') ?>"></span><?= $b->last_sync_status ? html_escape(ucfirst($b->last_sync_status)) : 'Belum pernah' ?><?php if($b->last_sync_message): ?><div class="small text-danger text-truncate" style="max-width:240px" title="<?= html_escape($b->last_sync_message) ?>"><?= html_escape($b->last_sync_message) ?></div><?php endif ?></td><td><?= $b->last_sync_at ? date('d M Y H:i',strtotime($b->last_sync_at)) : '—' ?></td><td><div class="btn-list flex-nowrap"><?php if($can('visits.sync')): ?><?= form_open('faskes/'.$b->id.'/sync') ?><button class="btn btn-sm btn-teal" type="submit">Sinkron</button><?= form_close() ?><?php endif ?><?php if($can('branches.manage')): ?><?= form_open('faskes/'.$b->id.'/test') ?><button class="btn btn-sm" type="submit">Tes</button><?= form_close() ?><a class="btn btn-sm" href="<?= site_url('faskes/'.$b->id.'/edit') ?>">Ubah</a><?php endif ?></div></td></tr><?php endforeach ?><?php if(!$branches): ?><tr><td colspan="5" class="text-center text-secondary py-5">Belum ada faskes. Tambahkan fasilitas kesehatan pertama untuk memulai.</td></tr><?php endif ?></tbody></table></div></div>
